STATE_JSON_FILE = os.path.join(BASE_DIR, "portal_saved_state.json")

def load_persisted_portal_state():
    if os.path.exists(STATE_JSON_FILE):
        try:
            with open(STATE_JSON_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                return data.get("state"), data.get("updated_at")
        except Exception:
            pass
    try:
        row = q("SELECT state_json, updated_at FROM portal_state WHERE id=1", one=True)
        if row and row["state_json"]:
            return json.loads(row["state_json"]), row["updated_at"]
    except Exception:
        pass
    return None, None

def save_persisted_portal_state(state_obj, now_ts):
    try:
        with open(STATE_JSON_FILE, "w", encoding="utf-8") as f:
            json.dump({"state": state_obj, "updated_at": now_ts}, f, indent=2)
    except Exception:
        pass
    try:
        q("INSERT OR REPLACE INTO portal_state(id, state_json, updated_at) VALUES(1, ?, ?)",
          (json.dumps(state_obj), now_ts), commit=True)
    except Exception:
        pass
