def _merge_states(existing_state, incoming):
    if not existing_state:
        return incoming
    merged = dict(existing_state)
    # Merge users (preserve any user whose permanent password was set: pwChanged == True)
    if isinstance(incoming.get("users"), list):
        by_ident = {str(u.get("ident", "")).lower(): u for u in existing_state.get("users", [])}
        for u in incoming["users"]:
            k = str(u.get("ident", "")).lower()
            old_u = by_ident.get(k)
            if old_u and old_u.get("pwChanged") and not u.get("pwChanged"):
                continue
            by_ident[k] = u
        merged["users"] = list(by_ident.values())
    # Merge exams (use latest lock/schedule settings)
    if isinstance(incoming.get("exams"), list) and len(incoming["exams"]) > 0:
        merged["exams"] = incoming["exams"]
    # Merge attempts by (uid, eid)
    if isinstance(incoming.get("attempts"), list):
        att_map = {(a.get("uid"), a.get("eid")): a for a in existing_state.get("attempts", [])}
        for a in incoming["attempts"]:
            key = (a.get("uid"), a.get("eid"))
            old_a = att_map.get(key)
            if old_a and old_a.get("done") and not a.get("done"):
                att_map[key] = a
            else:
                att_map[key] = a
        merged["attempts"] = list(att_map.values())
    # Merge subs by (uid, qid)
    if isinstance(incoming.get("subs"), list):
        sub_map = {(s.get("uid"), s.get("qid")): s for s in existing_state.get("subs", [])}
        for s in incoming["subs"]:
            sub_map[(s.get("uid"), s.get("qid"))] = s
        merged["subs"] = list(sub_map.values())
    # Merge flags by id
    if isinstance(incoming.get("flags"), list):
        fl_map = {f.get("id"): f for f in existing_state.get("flags", []) if f.get("id") is not None}
        for f in incoming["flags"]:
            if f.get("id") is not None:
                fl_map[f.get("id")] = f
        # If incoming explicitly cleared flags when existing had flags and incoming is empty from admin clear:
        if len(incoming["flags"]) == 0 and len(existing_state.get("flags", [])) > 0:
            merged["flags"] = []
        else:
            merged["flags"] = list(fl_map.values())
    # Merge code drafts
    if isinstance(incoming.get("drafts"), dict):
        d_map = dict(existing_state.get("drafts") or {})
        d_map.update(incoming["drafts"])
        merged["drafts"] = d_map
    return merged

